class MountainRiverForksTest{public static void main(String[]args){int n=128,size=4096;float[] height=new float[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++){double r=Math.hypot(x-64,z-64);height[z*n+x]=(float)(35+350*Math.exp(-r*r/600));}var node=new TerrainGraph.Node(1,TerrainGraph.Type.RIVERS,0,0);node.values.put("sources",4.0);node.values.put("headwater",200.0);node.values.put("riverSpacing",256.0);node.values.put("width",7.0);node.values.put("mountainForks",8.0);var e=EnvironmentNodes.apply(node,new EnvironmentMap(height),null,n,size,62,83,()->false);if(e.forkRoots<1||e.mountainForks.size()<=e.forkRoots)throw new AssertionError("No recursive short forks");if(e.forkRiverGroups!=e.forkEligibleGroups)throw new AssertionError("Missing river groups: "+e.forkRiverGroups+"/"+e.forkEligibleGroups);boolean lowland=false;boolean recursive=false;for(var fork:e.mountainForks){if(fork.generation()==0&&fork.elevation()<67||fork.separation()<3)throw new AssertionError("Fork does not diverge naturally");if(fork.generation()==0&&fork.elevation()<180)lowland=true;if(fork.generation()>0)recursive=true;}for(var arm:e.mountainArms){double length=0;for(int i=1;i<arm.points().size();i++)length+=Math.hypot(arm.points().get(i).x()-arm.points().get(i-1).x(),arm.points().get(i).z()-arm.points().get(i-1).z());if(length>160)throw new AssertionError("Fork arm too long: "+length);}if(!lowland)throw new AssertionError("Lower rivers still excluded");if(!recursive)throw new AssertionError("Forks never split again");if(e.share(e.height).mountainForks!=e.mountainForks)throw new AssertionError("Graph dropped fork metadata");System.out.println("PASS: "+e.mountainForks.size()+" short river junctions branch recursively with arm lengths capped at 160 blocks; metadata survives downstream nodes");}}
